pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 depositAmount) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);

        // Fund the contract
        vm.deal(address(this), depositAmount);
        vm.prank(address(this));
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        // Owner calls withdrawAll
        vm.prank(address(this));
        try c.withdrawAll(recipient) {
            uint256 recipientBalanceAfter = recipient.balance;
            assertTrue(recipientBalanceAfter == recipientBalanceBefore + contractBalanceBefore);
        } catch {
            // If it reverts, the property doesn't apply; this is fine.
        }
    }
}

